export type DeliveryPreferences = {
  maximumFee: number;
  carriers: string[];
};

export interface NotificationSink {
  success(message: string): void;
  failure(message: string): void;
}

export class DeliveryPreferenceCoordinator {
  private saved: DeliveryPreferences | null = null;

  constructor(private readonly notifications: NotificationSink) {}

  submit(preferences: DeliveryPreferences): DeliveryPreferences {
    if (typeof preferences !== "object" || preferences === null ||
        !preferences.maximumFee || !Number.isFinite(preferences.maximumFee) ||
        !Array.isArray(preferences.carriers) || preferences.carriers.length === 0 ||
        preferences.carriers.some(carrier => typeof carrier !== "string" || carrier.length === 0)) {
      this.notifications.failure("Invalid preferences");
      throw new TypeError("Invalid preferences");
    }
    this.saved = { maximumFee: preferences.maximumFee, carriers: [...preferences.carriers] };
    this.notifications.success("Preferences saved");
    return { maximumFee: this.saved.maximumFee, carriers: [...this.saved.carriers] };
  }

  current(): DeliveryPreferences | null {
    return this.saved
      ? { maximumFee: this.saved.maximumFee, carriers: [...this.saved.carriers] }
      : null;
  }
}
