import { DeliveryPreferenceCoordinator, type DeliveryPreferences, type NotificationSink } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message);
}
function captures(fn: () => void): unknown {
  try { fn(); } catch (error) { return error; }
  return undefined;
}

const calls: string[] = [];
const sink: NotificationSink = {
  success(message) { calls.push(`success:${message}`); },
  failure(message) { calls.push(`failure:${message}`); }
};
const coordinator = new DeliveryPreferenceCoordinator(sink);
assert(coordinator.current() === null, 'initial state is null');
const input: DeliveryPreferences = { maximumFee: 0, carriers: ['Fast', 'Fast', ' Economy '] };
const result = coordinator.submit(input);
deepEqual(result, input, 'zero fee and preserved carriers accepted');
deepEqual(calls, ['success:Preferences saved'], 'success notification sent');
input.maximumFee = 99;
input.carriers[0] = 'Changed';
result.maximumFee = 88;
result.carriers.push('Extra');
deepEqual(coordinator.current(), { maximumFee: 0, carriers: ['Fast', 'Fast', ' Economy '] }, 'input and result are defensive');
const current = coordinator.current();
assert(current !== null, 'current exists');
if (current) current.carriers[0] = 'Mutated';
deepEqual(coordinator.current(), { maximumFee: 0, carriers: ['Fast', 'Fast', ' Economy '] }, 'current is defensive');

const invalid: unknown[] = [
  null,
  {},
  { maximumFee: -1, carriers: ['A'] },
  { maximumFee: NaN, carriers: ['A'] },
  { maximumFee: Infinity, carriers: ['A'] },
  { maximumFee: '0', carriers: ['A'] },
  { maximumFee: 1, carriers: [] },
  { maximumFee: 1, carriers: 'A' },
  { maximumFee: 1, carriers: [''] },
  { maximumFee: 1, carriers: ['A', 2] }
];
for (const value of invalid) {
  const before = coordinator.current();
  const error = captures(() => coordinator.submit(value as DeliveryPreferences));
  assert(error instanceof TypeError && error.message === 'Invalid preferences', 'invalid input throws specified TypeError');
  assert(calls[calls.length - 1] === 'failure:Invalid preferences', 'failure notification sent');
  deepEqual(coordinator.current(), before, 'invalid input leaves state unchanged');
}

const supplied = ['Only'];
const valid = { maximumFee: 1.25, carriers: supplied };
coordinator.submit(valid);
supplied.push('Later');
deepEqual(coordinator.current(), { maximumFee: 1.25, carriers: ['Only'] }, 'stored carriers do not alias supplied array');

